# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE 32

__global__ void upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N)
{
    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    // Skip blocks fully below the diagonal
    if (block_row > block_col) return;

    int row = block_row * TILE + threadIdx.y;
    int col = block_col * TILE + threadIdx.x;

    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    float acc = 0.0f;

    // For upper-triangular A and B, C[i,j] = sum_{k=i}^{j} A[i,k]*B[k,j]
    // k must satisfy: i <= k (A is upper tri) and k <= j (B is upper tri)
    // We iterate over tiles of k from block_row*TILE to (block_col+1)*TILE
    int k_start_block = block_row;  // first tile of k that can contribute
    int k_end_block = block_col;    // last tile of k that can contribute

    for (int kb = k_start_block; kb <= k_end_block; kb++) {
        int k_row = kb * TILE + threadIdx.y;  // row index for A tile load
        int k_col = kb * TILE + threadIdx.x;  // col index for B tile load

        // Load A[row, k_col] - valid if row <= k_col (upper tri) and in bounds
        if (row < N && k_col < N && row <= k_col)
            As[threadIdx.y][threadIdx.x] = A[row * N + k_col];
        else
            As[threadIdx.y][threadIdx.x] = 0.0f;

        // Load B[k_row, col] - valid if k_row <= col (upper tri) and in bounds
        if (k_row < N && col < N && k_row <= col)
            Bs[threadIdx.y][threadIdx.x] = B[k_row * N + col];
        else
            Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        // Accumulate dot product
        #pragma unroll
        for (int t = 0; t < TILE; t++) {
            acc += As[threadIdx.y][t] * Bs[t][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result only for upper triangular output elements
    if (row < N && col < N && row <= col) {
        C[row * N + col] = acc;
    }
}

torch::Tensor upper_triangular_matmul_cuda(torch::Tensor a, torch::Tensor b) {
    int N = a.size(0);
    auto c = torch::zeros_like(a);

    dim3 block(TILE, TILE);
    int grid_dim = (N + TILE - 1) / TILE;
    dim3 grid(grid_dim, grid_dim);

    upper_triangular_matmul_kernel<<<grid, block>>>(
        a.data_ptr<float>(),
        b.data_ptr<float>(),
        c.data_ptr<float>(),
        N
    );

    return c;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs matrix multiplication (C = A * B) for upper triangular matrices.
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, A, B):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs matrix multiplication for upper triangular matrices.

                Args:
                    A (torch.Tensor): Upper triangular matrix of shape (N, N).
                    B (torch.Tensor): Upper triangular matrix of shape (N, N).

                Returns:
                    torch.Tensor: The product of A and B, also an upper triangular matrix of shape (N, N).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if (A.is_cuda and B.is_cuda and A.dtype == torch.float32 and B.dtype == torch.float32 and A.dim() == 2 and B.dim() == 2 and A.size(0) == A.size(1) and B.size(0) == B.size(1) and A.size(0) == B.size(0) and A.is_contiguous() and B.is_contiguous():
                    return _stark_get_extension().upper_triangular_matmul(A, B)
